WITH flattened_attrs AS (SELECT id, service, level, context['region'] AS region, CAST((status_code & 4) != 0 AS INT) AS is_flagged, context['trace'] AS trace, SIZE(context) AS num_context, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs WHERE service = 'search') SELECT service, MIN(num_context) AS min_num_context, MAX(is_flagged) AS max_is_flagged, SIZE(COLLECT_SET(level)) AS num_levels, AVG(status_code_high) FILTER (WHERE service = 'checkout') AS checkout_avg_status_code_high, SUM(num_context) FILTER (WHERE level = 'INFO') AS info_total_num_context, GROUPING(service) AS grouping_level FROM flattened_attrs GROUP BY ROLLUP (service) ORDER BY max_is_flagged DESC NULLS LAST;
